from typing import List
Matrix = List[List[float]]
def construct_gram_ntk(jacobian: Matrix) -> Matrix:
    """Return the sample Gram matrix J J^T in O(n^2 p) time."""
    return [[sum(x*y for x,y in zip(row_i,row_k))
             for row_k in jacobian] for row_i in jacobian]

